#include "Demos/TriggerAnimationSurfaceDemo.h"

#include <cstdio>
#include <fstream>

int main(){using namespace NeoEngine;const char* output="/tmp/fauzanengine_trigger_animation_surface_demo_smoke.ppm";TriggerAnimationSurfaceDemoConfig invalid{};invalid.frames=3U;TriggerAnimationSurfaceDemoReceipt receipt{};TriggerAnimationSurfaceDemoError error{};if(RunTriggerAnimationSurfaceDemo(invalid,receipt,error)||error!=TriggerAnimationSurfaceDemoError::InvalidConfiguration)return 1;TriggerAnimationSurfaceDemoConfig config{};config.width=96U;config.height=64U;config.frames=4U;config.hiddenSurface=true;config.ppmPath=output;if(!RunTriggerAnimationSurfaceDemo(config,receipt,error)||receipt.renderedFrames!=4U||receipt.presentedFrames!=4U||receipt.visiblePixels==0U||receipt.enteredEvents!=1U||receipt.exitedEvents!=1U||receipt.activeTintFrames!=2U||receipt.frameHash==0U||receipt.tintHash==0U||receipt.finalX!=0.75F||receipt.finalAnimationSample!=0.0F)return 1;std::ifstream artifact(output,std::ios::binary);char header[2]{};if(!artifact.read(header,2)||header[0]!='P'||header[1]!='6')return 1;artifact.close();std::remove(output);std::printf("TRIGGER_ANIMATION_SURFACE_DEMO_SMOKE_OK frames=%u enter=%u exit=%u tint=%u x=%.3f hash=%llu\n",receipt.renderedFrames,receipt.enteredEvents,receipt.exitedEvents,receipt.activeTintFrames,receipt.finalX,static_cast<unsigned long long>(receipt.frameHash));return 0;}
